〔プログラム5〕

public class AnEvaluator implements Evaluator<String> {
    public boolean evaluate(String s) {
        if (s != null) {
            final int len = s.length();
            for (int i = 0; i < len - 1; i++) {
                for (int j = i + 1; j < len; j++) {
                    if (s.charAt(i) == s.charAt(j)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }
}

